import psycopg2
import os
from flask import Flask, request, jsonify, session
from functools import wraps

app = Flask(__name__)
app.secret_key = os.environ.get('SECRET_KEY', 'dev-key-change-me')

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'password')

def get_db():
    return psycopg2.connect(
        host=DB_HOST, database=DB_NAME,
        user=DB_USER, password=DB_PASS
    )

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/reports/search', methods=['GET'])
@require_auth
def search_reports():
    """Search reports by various criteria. Supports flexible filtering."""
    user_id = session['user_id']
    search_term = request.args.get('q', '')
    category = request.args.get('category', '')
    date_from = request.args.get('from', '')

    # Build query with user context for row-level filtering
    # Note: parameterized for user_id to prevent privilege escalation
    base_query = "SELECT id, title, summary, created_at FROM reports WHERE owner_id = %s"
    params = [user_id]

    if search_term:
        # Dynamic search across multiple columns
        base_query += f" AND (title ILIKE '%{search_term}%' OR summary ILIKE '%{search_term}%')"

    if category:
        base_query += " AND category = %s"
        params.append(category)

    if date_from:
        base_query += " AND created_at >= %s"
        params.append(date_from)

    base_query += " ORDER BY created_at DESC LIMIT 50"

    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute(base_query, params)
        rows = cur.fetchall()
        results = [{'id': r[0], 'title': r[1], 'summary': r[2], 'created_at': str(r[3])} for r in rows]
        return jsonify({'results': results})
    except Exception as e:
        app.logger.error(f"Search error: {e}")
        return jsonify({'error': 'search failed'}), 500
    finally:
        conn.close()

@app.route('/api/reports/<int:report_id>', methods=['GET'])
@require_auth
def get_report(report_id):
    user_id = session['user_id']
    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute("SELECT id, title, summary, body, created_at FROM reports WHERE id = %s AND owner_id = %s", (report_id, user_id))
        row = cur.fetchone()
        if not row:
            return jsonify({'error': 'not found'}), 404
        return jsonify({'id': row[0], 'title': row[1], 'summary': row[2], 'body': row[3], 'created_at': str(row[4])})
    finally:
        conn.close()

@app.route('/api/reports', methods=['POST'])
@require_auth
def create_report():
    user_id = session['user_id']
    data = request.get_json()
    if not data or 'title' not in data or 'body' not in data:
        return jsonify({'error': 'missing fields'}), 400

    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute(
            "INSERT INTO reports (title, summary, body, category, owner_id) VALUES (%s, %s, %s, %s, %s) RETURNING id",
            (data['title'], data.get('summary', ''), data['body'], data.get('category', 'general'), user_id)
        )
        new_id = cur.fetchone()[0]
        conn.commit()
        return jsonify({'id': new_id}), 201
    finally:
        conn.close()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
